def parse(text):
    if not text:
        return []

    rows = []
    current_row = []
    current_field = []
    i = 0
    n = len(text)
    in_quotes = False

    while i < n:
        c = text[i]

        if in_quotes:
            if c == '"':
                if i + 1 < n and text[i+1] == '"':
                    current_field.append('"')
                    i += 2
                    continue
                else:
                    in_quotes = False
                    i += 1
                    continue
            else:
                current_field.append(c)
                i += 1
                continue
        else:
            if c == '"':
                in_quotes = True
                i += 1
                continue
            elif c == ',':
                current_row.append(''.join(current_field))
                current_field = []
                i += 1
                continue
            elif c == '\r':
                if i + 1 < n and text[i+1] == '\n':
                    i += 2
                else:
                    i += 1
                current_row.append(''.join(current_field))
                rows.append(current_row)
                current_row = []
                current_field = []
                continue
            elif c == '\n':
                current_row.append(''.join(current_field))
                rows.append(current_row)
                current_row = []
                current_field = []
                i += 1
                continue
            else:
                current_field.append(c)
                i += 1
                continue

    if current_field or current_row:
        current_row.append(''.join(current_field))
        rows.append(current_row)

    return rows


def format(rows):
    formatted_rows = []
    for row in rows:
        fields = []
        for field in row:
            if not field:
                fields.append('')
            else:
                needs_quote = False
                if ',' in field or '"' in field or '\r' in field or '\n' in field:
                    needs_quote = True
                elif field != field.strip():
                    needs_quote = True

                if needs_quote:
                    escaped = field.replace('"', '""')
                    fields.append(f'"{escaped}"')
                else:
                    fields.append(field)
        formatted_rows.append(','.join(fields))

    return '\n'.join(formatted_rows)
