SCALE = 10000

def parse(text: str) -> int:
    if not isinstance(text, str):
        raise ValueError("Input must be a string")
    text = text.strip()
    if not text:
        raise ValueError("Empty string")

    sign = 1
    if text[0] in '+-':
        sign = -1 if text[0] == '-' else 1
        text = text[1:]

    if not text:
        raise ValueError("Invalid format")

    if text.count('.') > 1:
        raise ValueError("More than one decimal point")

    if not all(c.isdigit() or c == '.' for c in text):
        raise ValueError("Non-digit characters")

    parts = text.split('.')
    int_part = parts[0]
    frac_part = parts[1] if len(parts) > 1 else ""

    if len(frac_part) > 4:
        raise ValueError("More than 4 decimal places")

    frac_part = frac_part.ljust(4, '0')

    val = int(int_part) * SCALE + int(frac_part)
    return sign * val

def format(value: int) -> str:
    sign = "-" if value < 0 else ""
    abs_val = abs(value)
    int_part = abs_val // SCALE
    frac_part = abs_val % SCALE
    return f"{sign}{int_part}.{frac_part:04d}"

def add(a: int, b: int) -> int:
    return a + b

def sub(a: int, b: int) -> int:
    return a - b

def mul(a: int, b: int) -> int:
    x = a * b
    if x < 0:
        q, r = divmod(-x, SCALE)
        if r * 2 >= SCALE:
            q += 1
        return -q
    else:
        q, r = divmod(x, SCALE)
        if r * 2 >= SCALE:
            q += 1
        return q

def div(a: int, b: int) -> int:
    if b == 0:
        raise ZeroDivisionError("division by zero")

    numerator = a * SCALE
    if numerator < 0:
        q, r = divmod(-numerator, b)
        if r * 2 >= abs(b):
            q += 1
        return -q
    else:
        q, r = divmod(numerator, b)
        if r * 2 >= abs(b):
            q += 1
        return q

def to_float(value: int) -> float:
    return value / SCALE
