def merge(intervals):
    if not intervals:
        return []

    valid = []
    for s, e in intervals:
        if s > e:
            raise ValueError(f"Invalid interval: ({s}, {e})")
        if s < e:
            valid.append((s, e))

    if not valid:
        return []

    valid.sort(key=lambda x: x[0])
    merged = [valid[0]]

    for s, e in valid[1:]:
        prev_s, prev_e = merged[-1]
        if s <= prev_e:
            merged[-1] = (prev_s, max(prev_e, e))
        else:
            merged.append((s, e))

    return merged


