    if not a or not b:
        return []

    overlaps = []
    for ia in a:
        for ib in b:
            s = max(ia[0], ib[0])
            e = min(ia[1], ib[1])
            if s < e:
                overlaps.append((s, e))

    return merge(overlaps)


