import math

def mean(xs):
    n = len(xs)
    if n == 0:
        raise ValueError("Empty sequence")
    return sum(xs) / n

def median(xs):
    s = sorted(xs)
    n = len(s)
    if n == 0:
        raise ValueError("Empty sequence")
    mid = n // 2
    if n % 2 == 1:
        return float(s[mid])
    return (s[mid - 1] + s[mid]) / 2.0

def variance(xs, sample=False):
    n = len(xs)
    if n == 0:
        raise ValueError("Empty sequence")
    if sample and n < 2:
        raise ValueError("Sample variance requires at least 2 values")
    m = mean(xs)
    ss = sum((x - m) ** 2 for x in xs)
    return ss / (n if not sample else n - 1)

def stdev(xs, sample=False):
    return math.sqrt(variance(xs, sample))

def percentile(xs, p):
    if not (0 <= p <= 100):
        raise ValueError("p must be between 0 and 100")
    n = len(xs)
    if n == 0:
        raise ValueError("Empty sequence")
    s = sorted(xs)
    k = (n - 1) * p / 100.0
    f = math.floor(k)
    c = math.ceil(k)
    if f == c:
        return float(s[int(k)])
    return s[f] + (k - f) * (s[c] - s[f])

def mode(xs):
    n = len(xs)
    if n == 0:
        raise ValueError("Empty sequence")
    counts = {}
    for x in xs:
        counts[x] = counts.get(x, 0) + 1
    max_count = max(counts.values())
    candidates = [x for x, c in counts.items() if c == max_count]
    return min(candidates)

def normalize(xs):
    m = mean(xs)
    s = stdev(xs, sample=False)
    return [(x - m) / s for x in xs]

def covariance(xs, ys, sample=False):
    if len(xs) != len(ys):
        raise ValueError("Sequences must have the same length")
    n = len(xs)
    if n == 0:
        raise ValueError("Empty sequence")
    if sample and n < 2:
        raise ValueError("Sample covariance requires at least 2 values")
    m_x = mean(xs)
    m_y = mean(ys)
    ss = sum((x - m_x) * (y - m_y) for x, y in zip(xs, ys))
    return ss / (n if not sample else n - 1)

def correlation(xs, ys):
    cov = covariance(xs, ys, sample=False)
    s_x = stdev(xs, sample=False)
    s_y = stdev(ys, sample=False)
    return cov / (s_x * s_y)
